import java.util.*;

class Solution {
  public int minimumDifference(int[] nums) {
    int half = nums.length / 2;
    List<Integer>[] left = subsetSums(Arrays.copyOfRange(nums, 0, half));
    List<Integer>[] right = subsetSums(Arrays.copyOfRange(nums, half, nums.length));
    int total = 0;
    for (int value : nums) total += value;
    int answer = Integer.MAX_VALUE;
    for (int count = 0; count <= half; count++) {
      List<Integer> candidates = right[half - count];
      Collections.sort(candidates);
      for (int first : left[count]) {
        int target = total / 2 - first;
        int index = Collections.binarySearch(candidates, target);
        if (index < 0) index = -index - 1;
        if (index < candidates.size())
          answer = Math.min(answer, Math.abs(total - 2 * (first + candidates.get(index))));
        if (index > 0)
          answer = Math.min(answer, Math.abs(total - 2 * (first + candidates.get(index - 1))));
      }
    }
    return answer;
  }

  private List<Integer>[] subsetSums(int[] values) {
    List<Integer>[] result = new List[values.length + 1];
    for (int i = 0; i <= values.length; i++) result[i] = new ArrayList<>();
    for (int mask = 0; mask < (1 << values.length); mask++) {
      int sum = 0;
      int count = 0;
      for (int bit = 0; bit < values.length; bit++) {
        if ((mask & (1 << bit)) != 0) {
          sum += values[bit];
          count++;
        }
      }
      result[count].add(sum);
    }
    return result;
  }
}
